import{_ as r,a0 as p,w as l,s as o,ao as s,I as i,x as u,a1 as n,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"每日Ubuntu小技巧：解決VirtualBox中截屏時的黑屏故障 | LCTT x X-CMD","titleTemplate":false,"description":"每日Ubuntu小技巧：解決VirtualBox中截屏時的黑屏故障 | LCTT (201404) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"每日Ubuntu小技巧：解決VirtualBox中截屏時的黑屏故障 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"每日Ubuntu小技巧：解決VirtualBox中截屏時的黑屏故障 | LCTT (201404) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201404/Daily Ubuntu Tips – Fix Black Screen In Ubuntu Guest With VirtualBox Screen Capture","title":"每日Ubuntu小技巧：解決VirtualBox中截屏時的黑屏故障","tag":"201404","desc":""},"relativePath":"201404/Daily Ubuntu Tips – Fix Black Screen In Ubuntu Guest With VirtualBox Screen Capture.md","filePath":"[post].md"}'),b={name:"201404/Daily Ubuntu Tips – Fix Black Screen In Ubuntu Guest With VirtualBox Screen Capture.md"};function x(d,t,T,m,U,g){const e=p("Link");return l(),o("div",null,[t[11]||(t[11]=s('<h1 id="每日ubuntu小技巧-解決virtualbox中截屏時的黑屏故障" tabindex="-1">每日Ubuntu小技巧：解決VirtualBox中截屏時的黑屏故障 <a class="header-anchor" href="#每日ubuntu小技巧-解決virtualbox中截屏時的黑屏故障" aria-label="Permalink to “每日Ubuntu小技巧：解決VirtualBox中截屏時的黑屏故障”">​</a></h1><p>VirtualBox是一個可以讓你在一台物理主機上運行多個系統的軟件。它支持Windows,Mac OS X 和Linux 並且是Oracle公司在維護它。</p><p>我們在這裏寫了很多關於VirtualBox的文章，你可以做一個快速的查找來查看所有關於VirtualBox的文章。</p><p>現在，這裏有一個故事：VirtualBox有一個功能，允許用户快速的截取虛擬機會話的屏幕截圖。這些截圖可以通過粘貼板和宿主機共享。</p><p>這就是我們這裏要説的了。當某一個Ubuntu 虛擬機中的功能啓用後，這項截圖的功能就不能夠正常的工作了。這種現象一直是一個痛點，直到最近我們偶然發現了這個解決方法。</p><p>如果不採取我們發現的這個方法，當你在Ubuntu的虛擬機裏面截完屏幕之後，截屏的圖片將會被存儲成全黑的文件，這樣的文件會毫無用處。</p><p>我一直在苦苦尋找解決方法，但是一直都沒有好運氣，直到剛剛。</p><p>要開啓Ubuntu下的虛擬機和宿主機之間的雙向黏貼板的話，請在Ubuntu虛擬機上面點擊 “設置”，之後找到“普通-&gt;高級標籤”，選擇這個功能來開啓它。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2014/02/virtualboxsharedclipboard.png" alt=""></p><p>現在，理論上，當你開啓Ubuntu的虛擬機之後，按下“截屏鍵”，或者按下“Ctrl+截屏鍵”，虛擬機就應該為當前的桌面會話來張截屏。</p><p>之後你就可以通過在宿主機上面使用粘貼板的功能來看到那些圖片了。</p><p><strong>但是！</strong>如果你同時啓用了Ubuntu虛擬機中的“3D 加速”功能，那些圖片將會變得漆黑一片。</p><p>為了解決這個問題，你必須關閉Ubuntu虛擬機的3D加速功能！</p><p>關閉3D加速功能可以這樣做：在Ubuntu虛擬機種點擊“設置”，之後找到“系統-&gt;顯示-&gt;顯卡”標籤，關閉3D加速</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2014/02/virtualboxsharedclipboard1.png" alt=""></p><p>現在你必須在Ubuntu的虛擬機中設置關閉3D加速才能讓截屏正常工作。現在打開一個虛擬機嘗試來截個屏幕吧。</p><p>希望這個方法能夠幫到你！</p><p>希望你喜歡！</p><hr>',19)),i("p",null,[t[1]||(t[1]=u("via: ",-1)),n(e,{href:"http://www.liberiangeek.net/2014/02/daily-ubuntu-tips-fix-black-screen-in-ubuntu-guest-with-virtualbox-screen-capture/"},{default:a(()=>[...t[0]||(t[0]=[u("http://www.liberiangeek.net/2014/02/daily-ubuntu-tips-fix-black-screen-in-ubuntu-guest-with-virtualbox-screen-capture/",-1)])]),_:1})]),i("p",null,[t[4]||(t[4]=u("譯者：",-1)),n(e,{href:"https://github.com/%E8%AD%AF%E8%80%85ID"},{default:a(()=>[...t[2]||(t[2]=[u("FineFan",-1)])]),_:1}),t[5]||(t[5]=u(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:a(()=>[...t[3]||(t[3]=[u("wxy",-1)])]),_:1})]),i("p",null,[t[8]||(t[8]=u("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[6]||(t[6]=[u("LCTT",-1)])]),_:1}),t[9]||(t[9]=u(" 原創翻譯，",-1)),n(e,{href:"http://linux.cn/"},{default:a(()=>[...t[7]||(t[7]=[u("Linux中國",-1)])]),_:1}),t[10]||(t[10]=u(" 榮譽推出",-1))])])}const C=r(b,[["render",x]]);export{w as __pageData,C as default};
